mapper.select:
SELECT cache.cache_id, source.cert_code, COALESCE(cache.contest_name, source.local_contest_name) AS contest_name, COALESCE(cache.recipient_name, source.local_name) AS recipient_name, COALESCE(cache.session, source.local_session) AS session, cache.contest_area, COALESCE(cache.runing_num_year, source.local_year) AS runing_num_year, cache.object_key, cache.file_name, cache.mime_type, cache.file_size, cache.sha256, COALESCE(cache.cache_status, 'PENDING') AS cache_status, COALESCE(cache.retry_count, 0) AS retry_count, cache.last_error, cache.next_retry_time, cache.last_sync_time, cache.create_time, cache.update_time FROM () source LEFT JOIN certificate_image_cache cache ON cache.cert_code = source.cert_code
AND (source.cert_code LIKE CONCAT('%', #{query.keyword}, '%') OR COALESCE(cache.recipient_name, source.local_name) LIKE CONCAT('%', #{query.keyword}, '%'))
AND COALESCE(cache.contest_name, source.local_contest_name) = #{query.contestName}
AND COALESCE(cache.session, source.local_session) = #{query.session}
AND cache.contest_area = #{query.contestArea}
AND COALESCE(cache.runing_num_year, source.local_year) = #{query.runingNumYear}
AND COALESCE(cache.cache_status, 'PENDING') = #{query.cacheStatus}
ORDER BY source.cert_code

SELECT * FROM certificate_image_cache WHERE cert_code IN
#{code}
ORDER BY cert_code

SELECT * FROM certificate_export_task
WHERE expires_at IS NOT NULL AND expires_at <= #{now}
  AND task_status IN ('COMPLETED', 'PARTIAL', 'FAILED')
ORDER BY expires_at LIMIT #{limit}
